const b = $json.body ?? $json;
const accion = String(b.accion ?? b.action ?? 'mensaje').trim().toLowerCase();
const ticket_id = Number.parseInt(String(b.ticket_id ?? '').replace(/\D/g, ''), 10) || 0;
const mensaje = String(b.mensaje ?? b.message ?? '').trim().slice(0, 2000);
const session_token = String(b.session_token ?? '').trim().slice(0, 200);
let error = '';
if (!['mensaje', 'solucionado', 'no_solucionado', 'escalar'].includes(accion)) error = 'Acción de chat no válida.';
else if (!ticket_id) error = 'Falta el número de ticket.';
else if (accion === 'mensaje' && mensaje.length < 2) error = 'Escribe un mensaje.';
return [{ json: { accion, ticket_id, mensaje, session_token, error } }];

const req = $('Validar petición de chat').first().json;
const t = $input.first().json;
const MAX = 3;
const responder = (respuesta) => [{ json: { route: 'responder', respuesta: { ticket_id: req.ticket_id, ...respuesta } } }];

if (req.error) return responder({ success: false, status: 'invalid', message: req.error });
if (!t.usuario_id) return responder({ success: false, status: 'unauthorized', message: 'Tu sesión expiró. Inicia sesión nuevamente.' });
if (!t.ticket_id) return responder({ success: false, status: 'not_found', message: 'No encontramos ese ticket en tu cuenta.' });
if (['Cerrado', 'Resuelto IA', 'Cancelado'].includes(t.estado))
  return responder({ success: false, status: 'closed', estado: t.estado, message: `Este ticket ya está finalizado (${t.estado}).` });
if (t.estado === 'Escalamiento pendiente')
  return responder({ success: true, status: 'escalar', estado: t.estado, message: 'Tu caso ya fue escalado. Completa los datos de la visita para asignarte un técnico.' });
if (!['Pendiente', 'En diagnóstico'].includes(t.estado))
  return responder({ success: true, status: 'escalated', estado: t.estado, message: `Tu caso está con el equipo técnico (estado: ${t.estado}). Te avisaremos por correo.` });

const intentos = Number(t.intentos_ia || 0);
const texto = `${t.descripcion_problema || ''} ${req.accion === 'mensaje' ? req.mensaje : ''}`
  .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const riesgo = /(humo|olor a quemado|quemad[oa]|liquido derramado|se (me )?mojo|mojad[oa]|bateria (hinchada|inflada)|chispa|riesgo electrico|descarga electrica|corto ?circuito|pantalla (rota|partida|quebrada))/.test(texto);

// Peligro para la persona (prioridad Crítica); el resto del daño físico escala con prioridad normal.
const peligro = /(humo|olor a quemado|quemad[oa]|bateria (hinchada|inflada)|chispa|riesgo electrico|descarga electrica|corto ?circuito)/.test(texto);
let route = req.accion, motivo = '', mensaje_escalamiento = '';
if (req.accion === 'solucionado') route = 'solucionado';
else if (riesgo) {
  route = 'escalar'; motivo = 'riesgo_fisico';
  mensaje_escalamiento = '⚠️ Por tu seguridad, desconecta el equipo de la corriente y no lo sigas usando. Este caso necesita revisión de un técnico: completa los datos de la visita.';
} else if (req.accion === 'escalar') {
  route = 'escalar'; motivo = 'solicitud_cliente';
  mensaje_escalamiento = 'Listo, te pasamos con el equipo técnico. Completa los datos de la visita.';
} else if (intentos >= MAX) {
  route = 'escalar'; motivo = 'limite_intentos';
  mensaje_escalamiento = `Agotamos los ${MAX} intentos con el asistente. Completa los datos para asignarte un técnico.`;
} else if (req.accion === 'no_solucionado') {
  return responder({ success: true, status: 'continue', intentos_usados: intentos, max_intentos: MAX,
    message: `Entiendo que no funcionó. Cuéntame qué ves ahora (mensajes de error, luces, sonidos) y te propongo otra alternativa. Te quedan ${MAX - intentos} intento(s) con el asistente.` });
}
return [{ json: { ...t, ...req, route, motivo, riesgo, peligro, mensaje_escalamiento } }];

