WITH upd AS (
  UPDATE public.tickets_soporte
     SET intentos_ia = intentos_ia + 1, estado = 'En diagnóstico', categoria = COALESCE(categoria, 'Software')
   WHERE id = $1 AND intentos_ia < 3 AND estado IN ('Pendiente', 'En diagnóstico')
  RETURNING id, intentos_ia, estado
), hist AS (
  INSERT INTO public.historial_chat (ticket_id, emisor, mensaje, intento_actual, metadata)
  SELECT id, 'usuario', $2, intentos_ia, jsonb_build_object('canal', 'web') FROM upd
)
SELECT upd.id AS ticket_id, upd.intentos_ia, upd.estado FROM (SELECT 1) seed LEFT JOIN upd ON true;

