const row = $input.first().json;
const ctx = $('Evaluar estado y seguridad').first().json;
if (!row.ticket_id) throw new Error('No se pudo registrar el mensaje: el ticket cambió de estado o no tiene intentos.');
const conocimiento = String(ctx.conocimiento || '').trim();
const prompt = [
  `Dispositivo: ${ctx.tipo_dispositivo || 'No especificado'}`,
  `Problema inicial: <cliente>${ctx.descripcion_problema}</cliente>`,
  `Mensaje actual: <cliente>${ctx.mensaje}</cliente>`,
  `Intento ${row.intentos_ia} de 3.`,
  `Historial reciente (del más antiguo al más reciente):\n${ctx.historial || '(sin historial)'}`,
  `Base de conocimiento interna (úsala si aplica, no inventes citas):\n${conocimiento || 'Sin artículos coincidentes; da solo recomendaciones generales seguras.'}`,
].join('\n\n');
return [{ json: { ticket_id: row.ticket_id, intentos_ia: row.intentos_ia, tiene_conocimiento: conocimiento !== '', prompt } }];

const ctx = $('Preparar contexto de diagnóstico').first().json;
const partes = $input.first().json.content?.parts || [];
const texto = partes.map((p) => p.text || '').join('').trim();
return [{ json: { ticket_id: ctx.ticket_id, intentos_ia: ctx.intentos_ia, tiene_conocimiento: ctx.tiene_conocimiento,
  error_ia: !texto,
  texto: texto || 'No pude generar una respuesta en este momento. Pulsa "No funcionó" para intentarlo de nuevo o pide un técnico.' } }];

