INSERT INTO public.historial_chat (ticket_id, emisor, mensaje, intento_actual, metadata)
VALUES ($1, 'IA', $2, $3, jsonb_build_object('modelo', 'gemini', 'uso_conocimiento', $4::boolean, 'error', $5::boolean))
RETURNING ticket_id, mensaje, intento_actual;

WITH upd AS (
  UPDATE public.tickets_soporte SET estado = 'Resuelto IA', fecha_cierre = now()
   WHERE id = $1 AND estado IN ('Pendiente', 'En diagnóstico')
  RETURNING id, nombre_completo, correo, estado, intentos_ia
), a AS (
  INSERT INTO public.auditoria_tickets (ticket_id, actor, accion, estado_anterior, estado_nuevo, detalle)
  SELECT id, 'cliente:' || $2, 'confirmacion_solucion', $3, 'Resuelto IA', jsonb_build_object('intentos_ia', intentos_ia) FROM upd
), h AS (
  INSERT INTO public.historial_chat (ticket_id, emisor, mensaje, intento_actual)
  SELECT id, 'usuario', 'El cliente confirmó que la solución funcionó.', intentos_ia FROM upd
)
SELECT upd.id AS ticket_id, upd.nombre_completo, upd.correo, upd.estado FROM (SELECT 1) seed LEFT JOIN upd ON true;
